import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { cancel, OrderStateError } from '../src/orders/domain/order.ts';
const own = {id:'probe-order-284',customerId:'alice',status:'pending' as const,items:['x','x','y']};
function setup(status = 'pending') {
 const orders = new InMemoryOrderStore([{...own,status:status as any},{...own,id:'other',customerId:'bob'}]);
 let writes=0;
 const save=orders.save.bind(orders); orders.save=o=>{writes++;save(o)};
 const router=orderRoutes(new Router(),{orders,sessions:{lookup:t=>t==='alice-session'?{id:'alice'}:t==='bob-session'?{id:'bob'}:undefined}});
 return {orders,get writes(){return writes},call:(auth?:string,id=own.id,body?:unknown)=>router.handle({method:'POST',path:`/orders/${id}/cancel`,headers:{authorization:auth},body})};
}
const a=setup(); const before=structuredClone(a.orders.all());
assert.equal(a.call('Bearer alice-session').status,200);
assert.deepEqual(a.orders.all(),[{...before[0],status:'cancelled'},before[1]]);assert.equal(a.writes,1);
console.log('R1 PASS: arbitrary ID, one write, full stored data preserved except status');
for(const auth of [undefined,'Bearer invalid','Basic alice-session','Bearer ','alice-session']) {
 const a=setup();const before=structuredClone(a.orders.all());assert.equal(a.call(auth).status,401);assert.equal(a.writes,0);assert.deepEqual(a.orders.all(),before);
}
console.log('R2 PASS: missing, invalid, inappropriate credentials: 401, zero writes');
for(const [auth,id] of [['Bearer bob-session',own.id],['Bearer alice-session','absent']]){
 const a=setup();const before=structuredClone(a.orders.all());assert.equal(a.call(auth,id,{customerId:'bob'}).status,404);assert.equal(a.writes,0);assert.deepEqual(a.orders.all(),before);
}
console.log('R3 PASS: foreign and absent orders: 404, zero writes despite body spoof');
for(const state of ['shipped','cancelled']) {
 assert.throws(()=>cancel({...own,status:state as any}),OrderStateError);
 const a=setup(state);const before=structuredClone(a.orders.all());assert.throws(()=>a.call('Bearer alice-session'),OrderStateError);assert.equal(a.writes,0);assert.deepEqual(a.orders.all(),before);
 console.log(`R4 invariant preserved; R5 FAIL: ${state} escapes as OrderStateError, zero writes`);
}
assert.throws(()=>a.call('Bearer alice-session'),OrderStateError);assert.equal(a.writes,1);
console.log('R4 replay cannot overwrite; R5 FAIL: replay throws instead of 4xx');
EOF
